  "landing.one.s7": "Πρόοδος",
  "landing.faq.title": "Συχνές ερωτήσεις",
  "landing.faq.q1": "Είναι το Second Brain απλώς ένα chatbot;",
  "landing.faq.a1": "Όχι. Είναι ένα προσωπικό μαθησιακό περιβάλλον: κατανοεί το περιεχόμενό σου, σε διδάσκει και θυμάται την πρόοδό σου με την πάροδο του χρόνου.",
  "landing.faq.q2": "Μπορώ να εργαστώ με πολλά PDF και έγγραφα;",
  "landing.faq.a2": "Ναι. Μπορείς να ομαδοποιήσεις PDF, φωτογραφίες, σαρώσεις και σημειώσεις σε ένα ολόκληρο θέμα και να μάθεις από το σύνολο, όχι από ένα μόνο αρχείο.",
  "landing.faq.q3": "Τι μπορώ να κάνω με τον Καθηγητή AI;",
  "landing.faq.a3": "Διδαχθείτε, ζητήστε εξηγήσεις, συζητήστε, κάντε καθοδηγούμενες συνεδρίες και εξασκηθείτε με ασκήσεις — προσαρμοσμένες στο επίπεδό σας.",
  "landing.faq.q4": "Μπορώ να μιλήσω στον AI Professor φωναχτά;",
  "landing.faq.a4": "Ναι. Η προφορική συνομιλία, οι προφορικές ασκήσεις και οι προφορικές εξετάσεις σάς επιτρέπουν να εξασκηθείτε φωναχτά.",
  "landing.faq.q5": "Τι είναι το Digital Twin;",
  "landing.faq.a5": "Μια εξατομικευμένη μνήμη της μάθησής σας — τι καταλαβαίνετε, κατέχετε, ξεχνάτε και στοχεύετε.",
  "landing.faq.q6": "Πώς λειτουργούν η μνήμη και η επανάληψη;",
  "landing.faq.a6": "Μs μηχανισμός διαστημικής επανάληψης (FSRS) προγραμματίζει επαναλήψεις τη σωστή στιγμή ώστε να συγκρατείτε περισσότερα με λιγότερη προσπάθεια.",
  "landing.faq.q7": "Μπορώ να χρησιμοποιήσω το Second Brain για την ακαδημαϊκή μου εργασία;",
  "landing.faq.a7": "Ναι. Το Academic Workspace καθοδηγεί εργαστήρια, εργασίες για το σπίτι, αναφορές και πολλά άλλα — διδάσκοντας τη μέθοδο, όχι απλώς την απάντηση.",
  "landing.faq.q8": "Πώς λειτουργεί η εκμάθηση γλωσσών;",
  "landing.faq.a8": "Εμβάπτιση, συνομιλία, προφορική εξάσκηση και shadowing — καθώς και βοήθεια στην κατανόηση της γλώσσας του δικού σας προγράμματος σπουδών.",
  "landing.faq.q9": "Πώς προστατεύονται τα δεδομένα μου;",
  "landing.faq.a9": "Τα δεδομένα μάθησής σας τροφοδοτούν την εμπειρία σας. Εσείς ελέγχετε τον λογαριασμό σας και μπορείτε να διαχειριστείτε τα δεδομένα σας από το προφίλ σας.",
