  "landing12.hero.scene.next.context": "Ορατή αιτιολόγηση · διατηρημένος προορισμός",
  "landing12.story.kicker": "Ένα προϊόν, μία εμπειρία",
  "landing12.story.title": "Δείτε τη γνώση να διασχίζει ολόκληρο το σύστημα",
  "landing12.story.lead": "Μια πηγή δεν σταματά στην αποθήκευση. Αυτή η επίδειξη ακολουθεί το ίδιο πλαίσιο από το έγγραφο έως την κατανόηση, την εξάσκηση, την επανάληψη και την ακαδημαϊκή παραγωγή.",
  "landing12.story.documents.title": "Ένα έγγραφο γίνεται αξιοποιήσιμη γνώση",
  "landing12.story.documents.short": "Έγγραφα",
  "landing12.story.documents.desc": "Η Βιβλιοθήκη λαμβάνει την πηγή. Η Νοημοσύνη Εγγράφου τη διαβάζει, εξάγει έννοιες και προετοιμάζει τεκμηριωμένες ερωτήσεις χωρίς να επινοεί πρόοδο.",
  "landing12.story.brain.title": "Οι έννοιες εντάσσονται σε έναν συνδεδεμένο γνωστικό χάρτη",
  "landing12.story.brain.short": "Ο Εγκέφαλός μου",
  "landing12.story.brain.desc": "Το γνωστικό δίδυμο κάνει ορατές έννοιες, σχέσεις, δυνατά σημεία και ευπάθειες. Αυτό το δημόσιο παράδειγμα είναι ενδεικτικό, όχι πραγματική βαθμολογία εκπαιδευόμενου.",
  "landing12.story.professor.title": "Ο Καθηγητής διδάσκει από το ίδιο πλαίσιο",
  "landing12.story.professor.short": "Καθηγητής AI",
  "landing12.story.professor.desc": "Το έγγραφο, η έννοια-στόχος και ο μαθησιακός στόχος ακολουθούν τη συνεδρία. Η εμπειρία μπορεί να γίνει εξήγηση, μάθημα, ερώτηση ή καθοδηγούμενη εξάσκηση.",
  "landing12.story.oral.title": "Η κατανόηση γίνεται προφορική εξάσκηση",
  "landing12.story.oral.short": "Προφορικά και Φωνή",
  "landing12.story.oral.desc": "Η ακρόαση, η μεταγραφή και η απάντηση είναι διακριτές, ευανάγνωστες καταστάσεις. Η μεταγραφή παραμένει ορατή· κανένα διακοσμητικό κύμα δεν προσποιείται ότι μετρά την ομιλία.",
  "landing12.story.review.title": "Μια εύθραυστη ιδέα γίνεται επανάληψη",
  "landing12.story.review.short": "Επανάληψη",
  "landing12.story.review.desc": "Η μηχανή επανάληψης εδραιώνει τη γνώση την κατάλληλη στιγμή. Η ημερομηνία εδώ είναι ρητά επίδειξη, όχι πραγματικό πρόγραμμα.",
  "landing12.story.workspace.title": "Η γνώση γίνεται παραδοτέο",
  "landing12.story.workspace.short": "Χώρος εργασίας",
  "landing12.story.workspace.desc": "Ο Ακαδημαϊκός Χώρος Εργασίας διατηρεί μαζί το σχέδιο, το κείμενο, τις πηγές και τις παραπομπές, ενώ ο βοηθός πλαισίου υποστηρίζει την εργασία του ίδιου του εκπαιδευόμενου.",
  "landing12.story.sharedContext": "Κοινό πλαίσιο",
  "landing12.story.traceability": "Ιχνηλασιμότητα πηγών",
  "landing12.story.outcome": "Δίνω πληροφορίες → το Second Brain τις κατανοεί → με διδάσκει → με βοηθά να εξασκηθώ → με βοηθά να θυμάμαι → με βοηθά να τις χρησιμοποιώ.",
  "landing12.story.nba": "Έπειτα προτείνει μια σαφή, εξηγήσιμη επόμενη ενέργεια αντί να με αφήνει σε έναν πίνακα ελέγχου.",
  "landing12.story.file": "Μάθημα βιολογίας.pdf",
