  "landing12.privacy.lead": "Το Second Brain περιλαμβάνει ελέγχους σε επίπεδο λογαριασμού για μνήμη, έγγραφα, φορητότητα και διαγραφή.",
  "landing12.privacy.scope": "Αυτοί είναι έλεγχοι προϊόντος, όχι πρόσθετη νομική υπόσχεση ή υπόσχεση ασφάλειας.",
  "landing12.privacy.memory": "Διαχείριση μνήμης AI",
  "landing12.privacy.export": "Εξαγωγή δεδομένων",
