  "landing12.privacy.delete": "Αίτημα διαγραφής λογαριασμού με επιβεβαίωση",
  "landing12.pricing.kicker": "Δωρεάν · Pro · Max",
  "landing12.pricing.title": "Τρεις ατομικές προσφορές, χωρίς επινοημένες λεπτομέρειες",
  "landing12.pricing.lead": "Οι οριστικές τιμές, τα όρια και τα οφέλη θα αποφασιστούν μετά τη δημόσια έκδοση beta. Η Σελίδα Υποδοχής παρουσιάζει μόνο τον πραγματικό κατάλογο σήμερα.",
  "landing12.pricing.free.name": "Δωρεάν",
  "landing12.pricing.free.desc": "Η προεπιλεγμένη ατομική προσφορά για να ανακαλύψετε την εμπειρία Second Brain.",
  "landing12.pricing.pro.name": "Pro",
  "landing12.pricing.pro.desc": "Μια προηγμένη ατομική προσφορά της οποίας η τελική τιμή, τα όρια και τα οφέλη δεν έχουν ακόμη ρυθμιστεί.",
  "landing12.pricing.max.name": "Max",
  "landing12.pricing.max.desc": "Η πιο εκτεταμένη ατομική προσφορά· οι τελικές εμπορικές λεπτομέρειές της δεν έχουν ακόμη ρυθμιστεί.",
  "landing12.pricing.freeStatus": "Διαθέσιμη δωρεάν προσφορά",
  "landing12.pricing.pending": "Λεπτομέρειες μετά τη δημόσια beta",
  "landing12.pricing.sourceNote": "Οι πιστοποιημένες οθόνες συνδρομής εξακολουθούν να τροφοδοτούνται από δεδομένα του συστήματος υποστήριξης. Καμία τιμή, έκπτωση, όριο ή αποκλειστικό όφελος δεν είναι ενσωματωμένο εδώ.",
  "landing12.faq.kicker": "Χρήσιμες απαντήσεις",
  "landing12.faq.title": "Έχετε ερωτήσεις; Απαντάμε.",
  "landing12.faq.lead": "Σύντομες απαντήσεις για όσα πραγματικά κάνει το προϊόν σήμερα.",
  "landing12.faq.q1": "Τι είναι το Second Brain;",
  "landing12.faq.a1": "Ένα προσωπικό έξυπνο σύστημα μάθησης που συνδέει ερωτήσεις, πηγές, διδασκαλία, εξάσκηση, μνήμη και ακαδημαϊκή εργασία σε ένα πλαίσιο.",
  "landing12.faq.q2": "Είναι απλώς ένα chatbot;",
  "landing12.faq.a2": "Όχι. Η συνομιλία είναι μία διεπαφή. Η ίδια συνεδρία μπορεί να γίνει μάθημα, προφορική άσκηση, ερώτηση με τεκμηρίωση εγγράφου, επανάληψη ή ενέργεια Χώρου Εργασίας.",
  "landing12.faq.q3": "Πώς λειτουργεί ο Εγκέφαλός μου;",
  "landing12.faq.a3": "Κάνει ορατές τις έννοιες, τις σχέσεις, τα στοιχεία κατάκτησης, τη μνήμη και το μαθησιακό ιστορικό σας. Προσαρμόζει την προβολή του στην ωριμότητα των διαθέσιμων δεδομένων.",
  "landing12.faq.q4": "Μπορώ να χρησιμοποιήσω τα δικά μου έγγραφα;",
  "landing12.faq.a4": "Ναι. Η Βιβλιοθήκη δέχεται υποστηριζόμενα αρχεία και σαρώσεις, εμφανίζει πραγματικές καταστάσεις επεξεργασίας, εξάγει έννοιες και υποστηρίζει τεκμηριωμένες ερωτήσεις και μετασχηματισμούς.",
  "landing12.faq.q5": "Μπορώ να μάθω μια γλώσσα;",
  "landing12.faq.a5": "Ναι. Η Μηχανή Γλώσσας Πραγματικής Ζωής συνδυάζει πρόγραμμα CEFR, ρητή γλωσσική εργασία, Αποστολές Πραγματικού Κόσμου, προφορική εξάσκηση, στοχευμένη αποκατάσταση, επανάληψη και στοιχεία Can-Do.",
  "landing12.faq.q6": "Πώς λειτουργεί ο Καθηγητής AI;",
  "landing12.faq.a6": "Χρησιμοποιεί το ενεργό πλαίσιο του εκπαιδευόμενου και μπορεί να εξηγεί, να διδάσκει, να ρωτά, να αξιολογεί ή να εξασκεί, διατηρώντας τη Συνεδρία Εμπειρίας.",
  "landing12.faq.q7": "Πώς λειτουργούν οι επαναλήψεις;",
  "landing12.faq.a7": "Η Επανάληψη χρησιμοποιεί πραγματικό ιστορικό και διακεκομμένη επανάληψη για να δίνει προτεραιότητα σε γνώσεις που κινδυνεύουν να ξεχαστούν. Η επανάληψη χωρίς AI παραμένει διαθέσιμη ανεξάρτητα από τα όρια AI.",
  "landing12.faq.q8": "Ποιες γλώσσες είναι διαθέσιμες;",
  "landing12.faq.a8": "Το κοινό μητρώο περιέχει αυτή τη στιγμή 34 γλώσσες μάθησης. Η γλώσσα διεπαφής και η γλώσσα μάθησης είναι πάντα ξεχωριστές επιλογές.",
  "landing12.faq.q9": "Η Έρευνα αναζητά στον Ιστό;",
  "landing12.faq.a9": "Η Έρευνα μπορεί σήμερα να λειτουργεί στον Εγκέφαλό μου και τη Βιβλιοθήκη σας. Ο εξωτερικός πάροχος Ιστού δεν έχει ρυθμιστεί στην τρέχουσα εγκατάσταση, οπότε η Σελίδα Υποδοχής δεν ισχυρίζεται ότι είναι.",
  "landing12.faq.q10": "Είναι ιδιωτικά τα δεδομένα μου;",
  "landing12.faq.a10": "Οι πιστοποιημένοι έλεγχοι καλύπτουν τη μνήμη AI, τα έγγραφα, τις συγκαταθέσεις, την εξαγωγή και τη διαγραφή λογαριασμού. Αυτή η σελίδα δεν προσθέτει νομικές ή τεχνικές υποσχέσεις πέρα από αυτούς τους ελέγχους.",
  "landing12.faq.q11": "Ποια είναι η διαφορά μεταξύ Δωρεάν, Pro και Max;",
  "landing12.faq.a11": "Είναι τα τρία επίπεδα ατομικών προγραμμάτων στον κατάλογο του συστήματος υποστήριξης. Οι τελικές τιμές, τα όρια και τα οφέλη θα ρυθμιστούν μετά τη δημόσια beta.",
  "landing12.faq.q12": "Πού μπορώ να χρησιμοποιήσω το Second Brain;",
  "landing12.faq.a12": "Η εμπειρία Ιστού είναι διαθέσιμη σε αυτή την εφαρμογή. Τα Android και iOS είναι τεχνικά έτοιμα χωρίς δημόσιους συνδέσμους καταστήματος· η διανομή για Windows και macOS αναμένεται.",
